-- ============================================================
-- INSERT PRODUCTOS - GRUPO TAPULLIMA & MANAYALLE SAC
-- Generado a partir de nueva_botica/reporte_stock_botica_2026-07-27233233.xlsx
-- 1325 productos (excluye filas de encabezado/pie del reporte).
--
-- Mapeo aplicado (ver aprendizaje_importacion_productos.md):
--   nombre <- DESCRIPCION | codigo/codigo_barras <- CODIGO (EAN)
--   codigo_interno <- SKU | categoria <- CATEGORIA (o 'NO PUESTO EN CATEGORIA')
--   unidad <- 'UND' fijo (mismo criterio que las cargas anteriores)
--   stock <- STOCK | precio_venta <- PV(*) | precio_compra <- PC(*)
--   laboratorio <- LABORATORIO (solo presente en parte de las filas)
--   PRECIO(*) se ignora (es 'Precio promedio contable', confirmado en el
--   pie del propio reporte -- no es el precio de venta real).
--
-- Excepcion aplicada: 1 codigo de barras (7750045258753) compartido por 2
-- productos reales distintos (paquete x15 y x1 de la misma marca). Para
-- esos 2, 'codigo' usa el SKU como respaldo (columna UNIQUE); 'codigo_barras'
-- conserva el barcode real en ambos.
--
-- Es un UPSERT (ON CONFLICT (codigo) DO UPDATE) para que sea seguro volver a
-- correr el script si se corrige el Excel -- OJO: si ya hay ventas reales
-- registradas, volver a correrlo SOBRESCRIBE el stock con el valor del Excel
-- (no es un delta). Pensado para la carga inicial antes de que la botica
-- empiece a vender, no para re-sincronizar despues de abrir.
--
-- USO:
--   psql -U postgres -d farmacia -c "SET search_path TO grupo_tapullima_manayalle_grupo_tapullima_mana, public;" -f database/insert_productos_grupo_tapullima_manayalle.sql
-- ============================================================

SET search_path TO grupo_tapullima_manayalle_grupo_tapullima_mana, public;

-- Categorias referenciadas (public.categorias es GLOBAL -- compartida por
-- todos los tenants/sucursales del sistema, ver migration_21).

-- Productos
LABOGEN.', (SELECT id FROM categorias WHERE nombre = 'MEDICAMENTOS GENERICOS Y JARABES GENERICOS.'), 'UND', NULL, 8.00, 2.50, 0.740) ON CONFLICT (codigo) DO UPDATE SET codigo_barras = EXCLUDED.codigo_barras, codigo_interno = EXCLUDED.codigo_interno, nombre = EXCLUDED.nombre, categoria_id = EXCLUDED.categoria_id, unidad = EXCLUDED.unidad, laboratorio = EXCLUDED.laboratorio, stock = EXCLUDED.stock, precio_venta = EXCLUDED.precio_venta, precio_compra = EXCLUDED.precio_compra, updated_at = CURRENT_TIMESTAMP;
PORTUGAL', (SELECT id FROM categorias WHERE nombre = 'MEDICAMENTOS GENERICOS Y JARABES GENERICOS.'), 'UND', NULL, 5.00, 0.50, 0.060) ON CONFLICT (codigo) DO UPDATE SET codigo_barras = EXCLUDED.codigo_barras, codigo_interno = EXCLUDED.codigo_interno, nombre = EXCLUDED.nombre, categoria_id = EXCLUDED.categoria_id, unidad = EXCLUDED.unidad, laboratorio = EXCLUDED.laboratorio, stock = EXCLUDED.stock, precio_venta = EXCLUDED.precio_venta, precio_compra = EXCLUDED.precio_compra, updated_at = CURRENT_TIMESTAMP;
VITAMINA E
BONAPHARM', (SELECT id FROM categorias WHERE nombre = 'VITAMINAS Y LECHES'), 'UND', NULL, 6.00, 1.00, 0.430) ON CONFLICT (codigo) DO UPDATE SET codigo_barras = EXCLUDED.codigo_barras, codigo_interno = EXCLUDED.codigo_interno, nombre = EXCLUDED.nombre, categoria_id = EXCLUDED.categoria_id, unidad = EXCLUDED.unidad, laboratorio = EXCLUDED.laboratorio, stock = EXCLUDED.stock, precio_venta = EXCLUDED.precio_venta, precio_compra = EXCLUDED.precio_compra, updated_at = CURRENT_TIMESTAMP;
VIVAMAS', (SELECT id FROM categorias WHERE nombre = 'VITAMINAS Y LECHES'), 'UND', NULL, 1.00, 60.00, 32.740) ON CONFLICT (codigo) DO UPDATE SET codigo_barras = EXCLUDED.codigo_barras, codigo_interno = EXCLUDED.codigo_interno, nombre = EXCLUDED.nombre, categoria_id = EXCLUDED.categoria_id, unidad = EXCLUDED.unidad, laboratorio = EXCLUDED.laboratorio, stock = EXCLUDED.stock, precio_venta = EXCLUDED.precio_venta, precio_compra = EXCLUDED.precio_compra, updated_at = CURRENT_TIMESTAMP;
 60 ML', (SELECT id FROM categorias WHERE nombre = 'NO PUESTO EN CATEGORIA'), 'UND', NULL, 1.00, 27.00, 12.000) ON CONFLICT (codigo) DO UPDATE SET codigo_barras = EXCLUDED.codigo_barras, codigo_interno = EXCLUDED.codigo_interno, nombre = EXCLUDED.nombre, categoria_id = EXCLUDED.categoria_id, unidad = EXCLUDED.unidad, laboratorio = EXCLUDED.laboratorio, stock = EXCLUDED.stock, precio_venta = EXCLUDED.precio_venta, precio_compra = EXCLUDED.precio_compra, updated_at = CURRENT_TIMESTAMP;
